SELECT r.id,r.content_generation,r.source_revision,COALESCE((SELECT IF(s.id IS NULL,'',SHA2(CAST(JSON_ARRAY('song',r.id,s.source,s.source_song_id,s.source_content_id,r.resource_kind,r.format_type) AS CHAR),256)) FROM song_source_refs s WHERE r.song_source_ref_id=s.id),''),r.status,r.claim_generation,COALESCE(r.running_batch_id,''),r.reference_sha256,r.reference_size_bytes,r.local_content_generation,r.local_target_revision,r.local_skip_generation,r.local_skip_target_revision,r.local_skip_baseline,r.local_skip_reason,COALESCE(r.local_path,''),COALESCE(r.checksum,''),r.size_bytes
FROM song_resources r WHERE r.id=? FOR UPDATE
